-- Dados de acidentes (planilha "Acidentes - POC.xlsx": 80 registros, 24/01/2024 a 08/10/2026).
-- Amplia a tabela com os campos da planilha; a coluna descricao guarda a característica do acidente.
alter table public.acidentes
  add column if not exists colaborador    text not null default '',
  add column if not exists processo       text not null default '',
  add column if not exists caracteristica text not null default '',
  add column if not exists supervisor     text not null default '',
  add column if not exists terceiros      text not null default '',
  add column if not exists cidade         text not null default '',
  add column if not exists base           text not null default '',
  add column if not exists gravidade      text not null default '',
  add column if not exists lesao          text not null default '';

-- Evita duplicar o mesmo acidente caso a carga seja repetida.
create unique index if not exists uq_acidentes_data_prefixo_colaborador
  on public.acidentes (data, prefixo, colaborador);

on conflict (data, prefixo, colaborador) do nothing;
